"slug":"kali-muriaticum","tags":["Kali Muriaticum"]},{"slug":"hydrogenium","tags":["Hydrogenium","водород"]},{"slug":"teucrium","tags":["Teucrium","чабрец"]},{"slug":"coccus-cacti","tags":["Coccus Cacti"]},{"slug":"camphora","tags":["Camphora","камфора"]},{"slug":"platina-metallicum","tags":["Platina Metallicum"]},{"slug":"baptisia-tinctoria","tags":["Baptisia Tinctoria"]},{"slug":"sanguinaria-canadensis","tags":["Sanguinaria Canadensis","Сангвинария, кровавый корень"]},{"slug":"veratrum-album","tags":["Veratrum Album"]},{"slug":"hydrastis-canadensis","tags":["Hydrastis Canadensis","Гидрастис, Золотарник канадский"]},{"slug":"cobaltum-metallicum","tags":["Cobaltum Metallicum","Кобальт"]},{"slug":"kalium-iodatum","tags":["Kalium Iodatum","Иодистый калий"]},{"slug":"colchicum-autumnale","tags":["Colchicum Autumnale","Безвременник"]},{"slug":"cocculus-indicus","tags":["Cocculus Indicus","Коккулюс, ядовитая лиана из Индии"]},{"slug":"aethusa-cynapium","tags":["Aethusa Cynapium","Собачья петрушка"]},{"slug":"beryllium-metallicum","tags":["Beryllium Metallicum","Бериллий / бериллий металл"]},{"slug":"bovista-lycoperdon","tags":["Bovista Lycoperdon","гриб пылевик"]},{"slug":"bothrops-lanceolatus","tags":["Bothrops Lanceolatus","Ботропс, копьеголовая змея"]},{"slug":"ambra-grisea","tags":["Ambra Grisea"]},{"slug":"folliculinum","tags":["Folliculinum","Женский половой гармон экстраген"]},{"slug":"helleborus-niger","tags":["Helleborus Niger","Черный морозник"]},{"slug":"magnesium-carbonicum","tags":["Magnesium Carbonicum"]},{"slug":"saccharum-officinale","tags":["Saccharum Officinale","Тростниковый сахар"]},{"slug":"cyclamen-europaeum","tags":["Cyclamen Europaeum","Цикламен / альпийская фиалка"]},{"slug":"syzygium-jambolanum","tags":["Syzygium jambolanum","Syzygiun Jambolanum"]},{"slug":"rock-water","tags":["Rock Water"]},{"slug":"saccharum-lactis","tags":["Saccharum Lactis","Молочный сахар"]},{"slug":"aconitum","tags":["Aconitum","Аконит","Аконитум","aconit","Aconite"]},{"slug":"medorrhinum","tags":["Medorrhinum","Медорринум"]},{"slug":"aqua-marina","tags":["Aqua Marina"]},{"slug":"luna","tags":["Luna"]},{"slug":"anandamide","tags":["Anandamide"]},{"slug":"cineraria","tags":["Cineraria","Cineraria Maritima","Цинерария","Пепельник приморский"]},{"slug":"amniotic-fluid","tags":["Amniotic Fluid","Околоплодные воды"]},{"slug":"placenta","tags":["Placenta","Плацента","Placentum"]},{"slug":"lac-amnioticum","tags":["Lac Amnioticum"]},{"slug":"aquamarinus","tags":["Aquamarinus"]},{"slug":"lac-caninum","tags":["Lac Caninum","Молоко собаки","Лак канинум"]},{"slug":"berberis","tags":["Berberis"]},{"slug":"plumbum-metallicum","tags":["Plumbum Metallicum","Plumbum","Свинец"]},{"slug":"helium","tags":["Helium"]},{"slug":"dolphin-milk","tags":["Dolphin Milk","Lac Delphinum","Молоко дельфина"]},{"slug":"crocus-sativus","tags":["Crocus Sativus"]},{"slug":"tuberculinum","tags":["Tuberculinum"]},{"slug":"moschus","tags":["Moschus"]},{"slug":"anacardium","tags":["Anacardium"]},{"slug":"magnesium-sulphiricum","tags":["Magnesium Sulphiricum","Magnesium Sulphuricum","Magnesium Sulfuricum"]},{"slug":"aspen","tags":["Aspen","Bach Aspen"]},{"slug":"white-chestnut","tags":["White Chestnut"]},{"slug":"x-ray","tags":["X-ray","Х-рей","X ray"]},{"slug":"north-pole","tags":["Северный Полюс","North Pole"]},{"slug":"nux-vomica","tags":["Nux Vomica","Nux","Нукс Вомика"]}]'::jsonb) AS x(slug text,tags jsonb)
), patched AS (
 UPDATE app.practitioner_articles a
 SET draft=jsonb_set(a.draft,'{tags}',s.tags,true),
     revision=a.revision+1,updated_at=now()
 FROM source s, app.practitioners p, app.practitioner_article_folders f
 WHERE a.practitioner_id=p.id AND a.folder_id=f.id AND f.practitioner_id=p.id
   AND p.slug='andy-litvinov' AND f.slug='remedy-cards' AND a.status='draft'
   AND a.slug=('remedy-' || s.slug || '-ru') AND NOT (a.draft ? 'tags')
 RETURNING a.id
)
SELECT count(*)::int AS enriched FROM patched;